				const isBearer = (mod.getBearerCredentialEnvVarNames?.() ?? []).some(
					(v) => {
						const raw = resolveEnv(v);
						return !!raw && raw === value;
					},
				);
				return { value, kind: isBearer ? "oauth" : "api-key" };
			});
			logger.debug("Provider upstreams registered with secret proxy");
		}
	}

