    messageId,
    ...(connectionId ? { connectionId } : {}),
    workspaceDir,
    platform,
    logger: createPluginLogger(logger),
  };
  const customTools = await runtimePluginHost.tools(pluginRuntimeContext);

  if (mcpExposure === "cli") {
    logger.info(
      "mcpExposure='cli' — skipping first-class MCP tool registration (tools reachable via <server> <tool> in Bash)."
    );
  }

  const modelRegistry = ModelRegistry.create(authStorage);

  // Rebuild final instructions after possible login link injection
  const finalInstructionsUpdated = instructionParts
    .filter(Boolean)
    .join("\n\n");

  logger.info(
    `Starting Lobu session: provider=${provider}, model=${modelId}, tools=${tools.length}, customTools=${customTools.length}`
  );

  // Heartbeat timer to keep connection alive during long API calls
  const HEARTBEAT_INTERVAL_MS = 20000;
  let heartbeatTimer: Timer | null = null;
  let deltaTimer: Timer | null = null;
  let session: Awaited<ReturnType<typeof buildAgentSession>>["session"] | null =
    null;
  // Fire the plugin `agent_end` hook with the live session messages. No-op
  // when the session never came up (the catch path before construction). An
  // `error` makes it a failure; its absence makes it a success.
  const emitAgentEnd = async (error?: string): Promise<void> => {
    if (!session) return;
    await runtimePluginHost.agentEnd(
      {
        ...(error !== undefined ? { error } : {}),
        messages: session.messages,
      },
      `- ⚠️ **${mcp.name}** (id: ${mcp.id}): No tools were discovered for this MCP in the current session. Do not assume a login tool exists unless it is actually registered.`
    );
  }

  return lines.join("\n");
}

/**
 * CLI-mode header introducing the `<server> <tool>` idiom. Appended to gateway
 * instructions when `mcpExposure === "cli"` so the model understands how to
 * invoke MCP tools through bash instead of as first-class function calls.
 */
function buildMcpCliInstructions(mcpStatus: McpStatus[]): string {
  if (!mcpStatus || mcpStatus.length === 0) return "";
  const servers = mcpStatus.map((m) => `- \`${m.id}\` — ${m.name}`).join("\n");
  return `## Available MCP CLIs

MCP servers are exposed as Bash commands. One command per server. Invoke tools by piping JSON on stdin:

\`\`\`bash
<server> <tool> <<'EOF'
{ ...json args... }
EOF
\`\`\`

Discovery:
- \`<server> --help\` — list a server's tools
- \`<server> <tool> --schema\` — print the JSON Schema for a tool
- \`<server> auth login|check|logout\` — manage OAuth where required

Servers:
${servers}`;
}

export function buildMcpServerInstructions(
  mcpInstructions: Record<string, string>
): string {
  // Sort by mcpId so the rendered block is byte-identical turn-to-turn
  // regardless of the map's key order. Non-deterministic ordering here would
  // reshuffle a stable-content block and needlessly bust the prompt cache.
