/**
 * Test Helpers
 *
 * HTTP client helpers for testing the Hono app directly (without starting a server).
 * Also includes MCP-specific helpers for JSON-RPC requests.
 *
 * MCP calls perform proper protocol initialization per session (keyed by token).
 */

import { app, type Env } from '../../index';
import { initWorkspaceProvider } from '../../workspace';

let workspaceReady: Promise<void> | null = null;

function ensureWorkspaceProvider(): Promise<void> {
  if (!workspaceReady) {
    workspaceReady = initWorkspaceProvider().then(() => {});
  }
  return workspaceReady;
}

// ============================================
// Test Environment
// ============================================

/**
 * Default test environment variables
 */
const testEnv: Env = {
  ENVIRONMENT: 'test',
  DATABASE_URL: process.env.DATABASE_URL,
  JWT_SECRET: 'test-jwt-secret-for-testing-only',
  BETTER_AUTH_SECRET: 'test-auth-secret-for-testing-only',
  MAX_CONSECUTIVE_FAILURES: '3',
  RATE_LIMIT_ENABLED: 'false', // Disable rate limiting in tests
  // Forward embeddings config when set in the host process (benchmark runs set these);
  // without this, content-search.ts sees env?.EMBEDDINGS_SERVICE_URL as undefined and
  // silently falls back to text-only ranking, even if embeddings are written to the DB.
  EMBEDDINGS_SERVICE_URL: process.env.EMBEDDINGS_SERVICE_URL,
  EMBEDDINGS_SERVICE_TOKEN: process.env.EMBEDDINGS_SERVICE_TOKEN,
  EMBEDDINGS_TIMEOUT_MS: process.env.EMBEDDINGS_TIMEOUT_MS,
};

// ============================================
// HTTP Client
// ============================================

interface TestResponse {
  status: number;
  headers: Headers;
  json: () => Promise<any>;
  text: () => Promise<string>;
}

/**
 * Make a request to the Hono app directly (no HTTP server needed)
 */
async function testRequest(
  method: string,
  path: string,
  options?: {
    body?: any;
    headers?: Record<string, string>;
    token?: string;
    cookie?: string;
    env?: Partial<Env>;
  }
): Promise<TestResponse> {
  await ensureWorkspaceProvider();
  const url = `http://localhost${path}`;
  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
    ...options?.headers,
  };

  if (options?.token) {
    headers.Authorization = `Bearer ${options.token}`;
  }

  if (options?.cookie) {
    headers.Cookie = options.cookie;
  }

  const request = new Request(url, {
    method,
    headers,
    body: options?.body ? JSON.stringify(options.body) : undefined,
  });

  // Merge test env with any overrides
  const env = { ...testEnv, ...options?.env };

  // Execute against Hono app with test environment
  const response = await app.fetch(request, env);

  return {
    status: response.status,
    headers: response.headers,
    json: () => response.json(),
    text: () => response.text(),
  };
}

// Convenience methods
export const get = (path: string, options?: Omit<Parameters<typeof testRequest>[2], 'body'>) =>
  testRequest('GET', path, options);

export const post = (path: string, options?: Parameters<typeof testRequest>[2]) =>
  testRequest('POST', path, options);

export const del = (path: string, options?: Omit<Parameters<typeof testRequest>[2], 'body'>) =>
  testRequest('DELETE', path, options);

/**
 * POST an `application/x-www-form-urlencoded` body — what a browser <form>
 * submit sends. Exercises routes that read via `c.req.parseBody()` (e.g. the
 * extension-bootstrap → /api/exchange-token handoff), which JSON bodies don't.
 */
export async function postForm(
  path: string,
  form: Record<string, string>,
  options?: { cookie?: string; env?: Partial<Env> }
): Promise<TestResponse> {
  await ensureWorkspaceProvider();
  const headers: Record<string, string> = {
    'Content-Type': 'application/x-www-form-urlencoded',
  };
  if (options?.cookie) headers.Cookie = options.cookie;
  const request = new Request(`http://localhost${path}`, {
    method: 'POST',
    headers,
    body: new URLSearchParams(form).toString(),
  });
  const env = { ...testEnv, ...options?.env };
  const response = await app.fetch(request, env);
  return {
    status: response.status,
    headers: response.headers,
    json: () => response.json(),
    text: () => response.text(),
  };
}

// ============================================
// MCP Session Management
// ============================================

import { mcpSessions } from './mcp-session-cache';

/**
 * Get or create an initialized MCP session for the given auth token.
 * Sends the proper initialize + notifications/initialized handshake
 * and caches the resulting session ID for subsequent requests.
 */
export async function ensureMcpSession(options?: {
  token?: string;
  env?: Partial<Env>;
  agentId?: string;
  orgSlug?: string;
  cookie?: string;
}): Promise<string> {
  const cookieKey = options?.cookie ? options.cookie.slice(0, 24) : '__no_cookie__';
  const cacheKey = `${options?.token ?? '__anonymous__'}:${options?.agentId ?? '__no_agent__'}:${options?.orgSlug ?? '__unscoped__'}:${cookieKey}`;

  const existing = mcpSessions.get(cacheKey);
  if (existing) return existing;

  // The unscoped `/mcp` endpoint never derives org context from an OAuth
  // token alone; pin to `/mcp/{orgSlug}` so the auth middleware sets
  // `c.var.organizationId`, matching what production MCP clients do.
  const mcpPath = options?.orgSlug ? `/mcp/${options.orgSlug}` : '/mcp';

  // 1. Send initialize
  const initResponse = await post(mcpPath, {
    body: {
      jsonrpc: '2.0',
      id: '__test_init__',
      method: 'initialize',
      params: {
        protocolVersion: '2025-03-26',
        capabilities: {},
        clientInfo: {
          name: 'lobu-test',
          version: '1.0',
          ...(options?.agentId ? { agentId: options.agentId } : {}),
        },
      },
    },
    token: options?.token,
    cookie: options?.cookie,
    env: options?.env,
  });

  const sessionId = initResponse.headers.get('mcp-session-id');
  if (!sessionId) {
    const body = await initResponse.json();
    throw new Error(
      `MCP initialize did not return session ID (status=${initResponse.status}): ${JSON.stringify(body)}`
    );
  }

  // 2. Send notifications/initialized
  await post(mcpPath, {
    body: {
      jsonrpc: '2.0',
      method: 'notifications/initialized',
    },
    headers: { 'mcp-session-id': sessionId },
    token: options?.token,
    cookie: options?.cookie,
    env: options?.env,
  });

  mcpSessions.set(cacheKey, sessionId);
  return sessionId;
}


// ============================================
// MCP JSON-RPC Helpers
// ============================================

interface MCPResponse<T = any> {
  jsonrpc: '2.0';
  id: number | string;
  result?: T;
  error?: { code: number; message: string; data?: any };
}

/**
 * Make an MCP JSON-RPC request (with proper session initialization)
 */
export async function mcpRequest<T = any>(
  method: string,
  params?: any,
  options?: {
    token?: string;
    env?: Partial<Env>;
    agentId?: string;
    orgSlug?: string;
  const token = input.tokenClaims;
  if (
    !token.channelId ||
    !token.runId ||
    !token.messageId ||
    token.runId !== input.payload.runId ||
    token.messageId !== input.payload.messageId
  ) {
    throw new Error("Durable agent input has invalid run token claims");
  }
  return {
    ...input.payload,
    runJobToken: generateWorkerToken(
      token.userId,
      token.conversationId,
      token.deploymentName,
      {
        channelId: token.channelId,
        teamId: token.teamId,
        agentId: token.agentId,
        organizationId: token.organizationId,
        connectionId: token.connectionId,
        responseThreadId: token.responseThreadId,
        platform: token.platform,
        source: token.source,
        sessionKey: token.sessionKey,
        traceId: token.traceId,
        runId: token.runId,
        messageId: token.messageId,
        adminTools: token.adminTools,
        runtimeProviderId: token.runtimeProviderId,
        sandboxId: token.sandboxId,
        allowedDomains: token.allowedDomains,
        deniedDomains: token.deniedDomains,
        nixPackages: token.nixPackages,
      },
    ),
  };
}

export async function recordAgentRunInput(
  payload: MessagePayload,
  deploymentName: string,
): Promise<void> {
  if (!payload.organizationId || typeof payload.runId !== "number") {
    throw new Error("Durable agent input requires organizationId and runId");
  }
  if (!payload.runJobToken) {
    throw new Error("Durable agent input requires a per-run token");
  }
  const token = verifyWorkerToken(payload.runJobToken);
  if (!token) {
    throw new Error("Durable agent input requires a valid per-run token");
  }
  assertTokenMatchesInput(token, payload, deploymentName);
  const storedPayload = { ...payload };
        ? formatBehaviorRunSkillInstructions(skillsConfig)
        : contextData.skillsInstructions || "";

      logger.info(
        `Session context for ${userId}: ${Object.keys(mcpConfig.mcpServers || {}).length} MCPs, ${contextData.agentLayers.identityMd.length}/${contextData.agentLayers.soulMd.length}/${contextData.agentLayers.userMd.length} chars identity/soul/user, ${contextData.platformInstructions.length} chars platform instructions, ${contextData.networkInstructions.length} chars network instructions, ${mergedSkillsInstructions.length} chars skills instructions, ${enrichedMcpStatus.length} MCP status entries, ${Object.keys(mcpTools).length} MCP tool lists, ${Object.keys(mcpInstructions).length} MCP instructions, ${skillsConfig.length} skills${behaviorRun ? " (Behavior run — pinned snapshot)" : ""}, provider: ${providerConfig.defaultProvider || "none"}`
      );

      return c.json({
        mcpConfig,
        agentLayers: contextData.agentLayers,
        platformInstructions: contextData.platformInstructions,
        networkInstructions: contextData.networkInstructions,
        skillsInstructions: mergedSkillsInstructions,
        mcpStatus: enrichedMcpStatus,
        mcpTools,
        mcpInstructions,
        mcpContext,
        providerConfig,
        skillsConfig,
        // The origin an agent can build user-openable Lobu links against.
        // Deliberately NOT `getRequestBaseUrl(c)`: this endpoint is called by
        // the worker over the INTERNAL dispatcher address, so the request Host
        // is a cluster name no user can reach. The configured public origin is
        // the only value here that is correct off-cluster.
        webOrigin: toPublicWebOrigin(this.publicGatewayUrl),
      });
    } catch (error) {
      logger.error("Failed to generate session context", { err: error });
      return c.json({ error: "session_context_error" }, 500);
    }
  }

  private async authenticateWorker(
    c: Context
  ): Promise<{ tokenData: WorkerTokenData; token: string } | null> {
    const authHeader = c.req.header("authorization");

    if (!authHeader?.startsWith("Bearer ")) {
      return null;
    }

    const token = authHeader.substring(7);
    const tokenData = verifyWorkerToken(token);

    if (!tokenData) {
      logger.warn("Invalid token");
      return null;
    }

    if (
      tokenData.jti &&
      (await getRevokedTokenStore().isRevoked(tokenData.jti))
    ) {
      logger.warn("Revoked worker token");
      return null;
    }

    return { tokenData, token };
  }

  /**
   * Mint a fresh same-claims token from a currently-valid one, so a >2h turn
   * doesn't die when its token hits the 2h TTL (the short TTL is the leak-
   * revocation path; this swaps the token without lengthening it).
   *
   * Contract: requires a valid per-run token (`runId` + `messageId`) AND a live
   * turn-timeout marker for the token's OWN turn ({@link hasLiveTurnForMessage}
   * on `(deploymentName, messageId)`). Gating per-turn — not per-deployment —
   * is the load-bearing invariant: it closes the cross-turn leak where a still-
   * valid token from a COMPLETED turn refreshes off a later, unrelated turn's
   * liveness on the same deployment. Expired (verifyWorkerToken) and jti-revoked
   * tokens are rejected before the gate; the fresh token gets its own jti.
   * Legacy direct-enqueue tokens (no runId/messageId → no marker) are denied.
   */
  private async handleTokenRefresh(c: Context): Promise<Response> {
    const auth = await this.authenticateWorker(c);
    if (!auth) {
      // Expired / malformed / jti-revoked — verifyWorkerToken or the
      // revoked-token check already rejected. An expired token CANNOT refresh
      // itself; that bounds the leak window.
      return c.json({ error: "Invalid token" }, 401);
    }
    const { tokenData } = auth;

    // No runId/messageId → no turn-timeout marker exists for this token's work,
    // so we have no per-turn liveness signal. Deny rather than mint blind.
    if (typeof tokenData.runId !== "number" || !tokenData.messageId) {
      return c.json({ error: "Token not eligible for refresh" }, 403);
    }

    if (!tokenData.deploymentName) {
      return c.json({ error: "Token missing deployment scope" }, 400);
    }

    const live = await hasLiveTurnForMessage(
      tokenData.deploymentName,
      tokenData.messageId
    );
    if (!live) {
      // THIS token's turn has no in-flight marker — the turn is terminal (reply
      // committed, worker died, or deadline swept), even if a later unrelated
      // turn on the same deployment is still live. Refusing here is the
      // revocation property: the token chain ends with the turn it was minted
      // for, so a completed turn's token can't piggyback on a newer turn.
      logger.info(
        {
          deploymentName: tokenData.deploymentName,
          runId: tokenData.runId,
          messageId: tokenData.messageId,
        },
        "Token refresh denied: no live turn for this message"
      );
      return c.json({ error: "No live turn for token" }, 403);
    }

    // Mint a fresh token with identical claims (fresh timestamp + new jti).
    const refreshed = generateWorkerToken(
      tokenData.userId,
      tokenData.conversationId,
      tokenData.deploymentName,
      {
        channelId: tokenData.channelId,
        teamId: tokenData.teamId,
        agentId: tokenData.agentId,
        organizationId: tokenData.organizationId,
        connectionId: tokenData.connectionId,
        responseThreadId: tokenData.responseThreadId,
        platform: tokenData.platform,
        source: tokenData.source,
        sessionKey: tokenData.sessionKey,
        traceId: tokenData.traceId,
        runId: tokenData.runId,
        messageId: tokenData.messageId,
        // Preserve the builder admin-tool allowlist across refresh — otherwise a
        // long system-agent turn loses its admin grant when the token rotates.
        adminTools: tokenData.adminTools,
        // Preserve the runtime selection — otherwise a remote-runtime worker's
        // bash starts failing (the generic route 404s with no provider claim)
        // after the token rotates mid-turn.
        runtimeProviderId: tokenData.runtimeProviderId,
        sandboxId: tokenData.sandboxId,
        // Preserve the egress allow/deny lists too — otherwise a refreshed
        // token would fall to deny-all (allow) or, worse, drop its exclusions
        // (deny) and re-open denied hosts mid-turn.
        allowedDomains: tokenData.allowedDomains,
        deniedDomains: tokenData.deniedDomains,
        // And the package claim with them — a long turn that rotates its token
        // would otherwise stop provisioning the connector's CLI mid-run.
        nixPackages: tokenData.nixPackages,
      }
    );

    logger.info(
      {
        deploymentName: tokenData.deploymentName,
        runId: tokenData.runId,
        messageId: tokenData.messageId,
      },
      "Issued refreshed worker token"
    );
    return c.json({ token: refreshed });

