export default async (_ctx, client) => {
  const t = await client.operations.execute({
    connection_id: 432,
    operation_key: "get_accessibility_tree",
    input: { tab_id: 558571879 }
  });
  const o = t.output || t;
  const tree = o.tree || [];
  return {
    epoch: o.document_epoch,
    matches: tree.filter((n) => /allow 1h|allow 24h|allow always|deny always|tool approval|run_sdk|deployment e2e|new messages|mark as read/i.test(JSON.stringify(n))).slice(-100),
    buttons: tree.filter((n) => n.role === "button").slice(-80)
  };
}

