      clientId,
      clientSecret,
      encryptionKey,
      installationKeyPrefix,
      userName,
    } = currentConfig;

    if (!signingSecret) {
      throw new Error("Slack signing secret is not configured. Set SLACK_SIGNING_SECRET.");
    }

    if (options?.requireOAuth) {
