  // detach orphaned it (generation moved since the entry was published — see
  // debugger-lease.js). A stale entry is dropped so we fall through to a real
  // reattach instead of resuming a dead listener on a lease reset to 0.
  const live = LIVE_SESSIONS.get(sessionId);
