  // new session. buildMatchers throws on empty/malformed patterns — only
  // enforced for new sessions; a resume inherits the stored patterns and must
  // not require the caller to re-send them.
  let effectivePatterns;
  let effectiveAllowedOrigins;
  let effectiveMaxBufferResponses;
  let effectiveMaxBodyBytes;
