    effectivePatterns = existing.patterns;
    effectiveAllowedOrigins = existing.allowed_origins ?? [];
    effectiveMaxBufferResponses = existing.max_buffer_responses;
    effectiveMaxBodyBytes = existing.max_body_bytes;
  } else {
    buildMatchers(args?.patterns); // validate; matchers rebuilt after attach
    effectivePatterns = args.patterns;
    effectiveAllowedOrigins = runCtx.allowedOrigins ?? [];
    effectiveMaxBufferResponses = clampInt(
      args?.max_buffer_responses,
      1,
      1000,
      DEFAULT_MAX_BUFFER_RESPONSES,
    );
    effectiveMaxBodyBytes = clampInt(
      args?.max_body_bytes,
      1024,
      10 * 1024 * 1024,
      DEFAULT_MAX_BODY_BYTES,
    );
  }

