    allowedOrigins: effectiveAllowedOrigins,
  });

  // Persist first so a SW eviction between start() and the CDP attach can't
  // leave a dangling listener / phantom buffer. Preserve the existing buffer.
  await writeSession(chromeApi, sessionId, {
    tab_id: effectiveTabId,
    patterns: effectivePatterns,
    allowed_origins: effectiveAllowedOrigins,
    max_buffer_responses: effectiveMaxBufferResponses,
    max_body_bytes: effectiveMaxBodyBytes,
    buffer: Array.isArray(existing?.buffer) ? existing.buffer : [],
    created_at: existing?.created_at ?? Date.now(),
  });

  // Take a shared debugger lease (see tools.js). If no one else is
  // attached on this tab, the lease attaches; if a withDebugger() action
  // tool currently holds the tab, the lease just bumps the refcount and
  // we ride the existing attach. We keep the lease for the session's
  // lifetime (intentionally NOT under withDebugger which auto-detaches at
  // end of fn), and release it in tool_network_intercept_stop when the
  // last live session on this tab ends. This is what makes a later
  // navigate / evaluate via withDebugger on the same tab safe: it sees a
  // non-zero lease, skips the attach, runs, decrements back. The 1→0
  // detach is deferred until intercept_stop.
  let lease;
  try {
    lease = await acquireDebuggerLease(chromeApi, effectiveTabId);
  } catch (err) {
    await deleteSession(chromeApi, sessionId);
    throw err;
  }

  try {
    await chromeApi.debugger.sendCommand(dbgTarget(effectiveTabId), 'Network.enable', {});
  } catch (err) {
    // If Network.enable fails the session is unusable; release the lease
    // we just acquired and clean up the persisted row.
    await releaseDebuggerLease(chromeApi, lease);
    await deleteSession(chromeApi, sessionId);
