  // reattach keeps matching what the original session was configured for.
  const matches = makeMatcher(buildMatchers(effectivePatterns));
  const requestIdToUrl = new Map(); // CDP requestId → URL (filled by responseReceived)
  const requestIdToMime = new Map();
  const requestIdToStatus = new Map();

  const listener = (source, method, params) => {
    if (source.tabId !== effectiveTabId) return;
    if (method === 'Network.responseReceived') {
      const url = params?.response?.url;
      if (!url || !matches(url)) return;
      if (!urlHostInAllowlist(url, effectiveAllowedOrigins)) return;
      requestIdToUrl.set(params.requestId, url);
      requestIdToMime.set(params.requestId, params.response?.mimeType ?? '');
      requestIdToStatus.set(params.requestId, params.response?.status ?? 0);
      return;
    }
    if (method === 'Network.loadingFinished') {
      const url = requestIdToUrl.get(params?.requestId);
      if (!url) return;
      const reqId = params.requestId;
