      // synchronously to keep CDP delivery in order.
      void captureBody(chromeApi, effectiveTabId, sessionId, reqId, url, {
        mime: requestIdToMime.get(reqId) ?? '',
        status: requestIdToStatus.get(reqId) ?? 0,
        maxBodyBytes: effectiveMaxBodyBytes,
        maxBufferResponses: effectiveMaxBufferResponses,
      });
      requestIdToUrl.delete(reqId);
      requestIdToMime.delete(reqId);
      requestIdToStatus.delete(reqId);
    }
