  // not a pre-acquire sample; store the lease so stop() releases with the same
  // token.
  LIVE_SESSIONS.set(sessionId, {
    tabId: effectiveTabId,
    detachGen: lease.generation,
    lease,
    listener,
    requestIdToUrl,
    requestIdToMime,
    requestIdToStatus,
  });

