/**
 * Postgres-backed `pending-tool:<requestId>` store. Backed by the
 * `oauth_states` table with a `pending-tool` scope so the MCP proxy
 * (writer) and the interaction bridge / CLI gateway (reader) can hand off
 * blocked-tool invocations through a single primitive.
 */

import { getDb } from "../../../db/client.js";

const SCOPE = "pending-tool";

export interface PendingToolInvocation {
  mcpId: string;
  toolName: string;
  args: Record<string, unknown>;
  agentId: string;
  userId: string;
	organizationId: string;
  channelId?: string;
  conversationId?: string;
  teamId?: string;
  connectionId?: string;
}

export async function storePendingTool(
  requestId: string,
  invocation: PendingToolInvocation,
	ttlSeconds: number,
): Promise<void> {
  const sql = getDb();
  const expiresAt = new Date(Date.now() + ttlSeconds * 1000);
  await sql`
    INSERT INTO oauth_states (id, scope, payload, expires_at)
    VALUES (${requestId}, ${SCOPE}, ${sql.json(invocation as object)}, ${expiresAt})
    ON CONFLICT (id) DO UPDATE SET
      scope = EXCLUDED.scope,
      payload = EXCLUDED.payload,
      expires_at = EXCLUDED.expires_at
  `;
}

/**
 * Read (without consuming) the unresolved pending-tool invocations for a
 * conversation. The live `tool-approval` SSE card is one-shot, so without this
 * a pending approval vanishes from the web UI on reload. The SPA fetches this
 * on load and replays open approvals as approval cards; resolution stays
 * claim-and-delete via `takePendingTool`, so a row surfaced here disappears the
 * moment the user approves/denies and never replays.
 *
 * `organizationId` is REQUIRED — it MUST be the caller's AUTHORIZED org
 * (resolved by the route's authorizeAgentAccess) and always scopes the read so a
 * row can never cross tenants, defense-in-depth on top of the conversationId
 * key. The route returns 403 when no org resolves rather than ever issuing an
 * unscoped read.
 */
export async function listPendingToolsForConversation(
	conversationId: string,
	organizationId: string,
): Promise<Array<PendingToolInvocation & { requestId: string }>> {
	const sql = getDb();
	const rows = await sql`
    SELECT id, payload
    FROM oauth_states
    WHERE scope = ${SCOPE}
      AND expires_at > now()
      AND payload->>'conversationId' = ${conversationId}
      AND payload->>'organizationId' = ${organizationId}
    ORDER BY expires_at ASC
  `;
	return rows.map((r) => {
		const row = r as { id: string; payload: PendingToolInvocation };
		return { ...row.payload, requestId: row.id };
	});
}

/**
 * Atomically fetch and delete a pending tool invocation. Used by the
 * interaction bridge / CLI approve handler to claim the row exactly
 * once — Slack/Telegram webhook retries that arrive after the first
 * click see null and no-op.
 */
export async function takePendingTool(
	requestId: string,
): Promise<PendingToolInvocation | null> {
  const sql = getDb();
  const rows = await sql`
    DELETE FROM oauth_states
    WHERE id = ${requestId}
      AND scope = ${SCOPE}
      AND expires_at > now()
    RETURNING payload
  `;
  if (rows.length === 0) return null;
	return (rows[0] as { payload: PendingToolInvocation }).payload ?? null;
}

/** Active tool approvals belonging to this Behavior run's agent session. */
export async function listPendingToolsForRun(
	runId: number,
	sql: ReturnType<typeof getDb>
): Promise<Array<{ mcpId: string; toolName: string }>> {
	const rows = await sql`
    SELECT DISTINCT
      pending.payload->>'mcpId' AS mcp_id,
      pending.payload->>'toolName' AS tool_name
    FROM oauth_states pending
    JOIN runs behavior_run
      ON behavior_run.id = ${runId}
     AND behavior_run.run_type = 'behavior'
    WHERE pending.scope = ${SCOPE}
      AND pending.expires_at > now()
      AND pending.payload->>'organizationId' = behavior_run.organization_id
      AND right(
        pending.payload->>'conversationId',
        length(
          '_watcher_' || behavior_run.watcher_id::text ||
          '_run_' || behavior_run.id::text
        )
      ) = '_watcher_' || behavior_run.watcher_id::text ||
          '_run_' || behavior_run.id::text
    ORDER BY mcp_id, tool_name
  `;
	return rows
		.map((r) => r as { mcp_id: string | null; tool_name: string | null })
		.filter((r) => r.mcp_id && r.tool_name)
		.map((r) => ({ mcpId: r.mcp_id as string, toolName: r.tool_name as string }));
}
	/**
	 * Shared tool-approval gate used by the REST (`handleCallTool`) and JSON-RPC
	 * (`handleProxyRequest`) call paths. Resolves tool annotations, checks the
	 * grant store, and — if blocked — stores the pending invocation and fires
	 * `onToolBlocked`. Returns:
	 * - `"allow"`: not blocked (no approval needed, or a grant exists);
	 * - `"blocked-notified"`: blocked and the user was asked to approve;
	 * - `"blocked-no-channel"`: blocked but no `onToolBlocked` handler is wired,
	 *   so no approval card could be sent.
	 *
	 * @internal Public only for the route-handler modules.
	 */
	async evaluateToolApproval(
		mcpId: string,
		toolName: string,
		toolArgs: Record<string, unknown>,
		agentId: string,
		tokenData: WorkerTokenData,
		token: string,
	): Promise<"allow" | "blocked-notified" | "blocked-no-channel"> {
		if (!this.grantStore) return "allow";

		const { found, annotations } = await this.getToolAnnotations(
			mcpId,
			toolName,
			agentId,
			tokenData,
			token,
		);
		// Fail closed: when tool annotations can't be fetched (upstream error,
		// SSRF block, timeout, etc.), `found` is false. The previous behaviour
		// returned "allow" here, which let destructive tools bypass approval
		// whenever discovery failed. Require approval unless we have annotations
		// that explicitly say the tool is safe.
		if (found && !requiresToolApproval(annotations)) return "allow";

		const pattern = `/mcp/${mcpId}/tools/${toolName}`;
		if (await this.grantStore.hasGrant(agentId, pattern)) return "allow";

		logger.info("Tool call blocked: requires approval", {
			agentId,
			mcpId,
			toolName,
			pattern,
		});

		if (!this.onToolBlocked) return "blocked-no-channel";
		if (!tokenData.organizationId) {
			logger.error(
				{ agentId, mcpId, toolName },
				"Refusing to store pending MCP tool approval without organizationId",
			);
			return "blocked-no-channel";
		}

		const requestId = `ta_${randomUUID()}`;
		await storePendingTool(
			requestId,
			{
				mcpId,
				toolName,
				args: toolArgs,
				agentId,
				userId: tokenData.userId,
				organizationId: tokenData.organizationId,
				channelId: tokenData.channelId || "",
				conversationId: tokenData.conversationId || "",
				teamId: tokenData.teamId,
				connectionId: tokenData.connectionId,
			},
			this.PENDING_TOOL_TTL,
		).catch((err: unknown) =>
			logger.error(
				{ requestId, error: String(err) },
				"Failed to store pending tool invocation",
			),
		);

		await this.onToolBlocked(
			requestId,
			agentId,
			tokenData.userId,
			mcpId,
			toolName,
			toolArgs,
			pattern,
			tokenData.channelId || "",
			tokenData.conversationId || "",
			tokenData.teamId,
			tokenData.connectionId,
			tokenData.platform,
			tokenData.source,
		).catch((err) =>
			logger.error(
				{ requestId, error: String(err) },
				"onToolBlocked callback failed",
			),
		);

		return "blocked-notified";
	}

