export function buildUpstreamHeaders(
	sessionId: string | null,
	credentialToken?: string,
	internal?: boolean,
): Record<string, string> {
	const headers: Record<string, string> = {
		"Content-Type": "application/json",
		// MCP streamable-HTTP spec requires both — servers like DeepWiki reject
		// plain `application/json` with 406 Not Acceptable.
		Accept: "application/json, text/event-stream",
	};

	if (credentialToken) {
		headers.Authorization = `Bearer ${credentialToken}`;
	}

	// Stamp internal MCP requests so the embedded Lobu multi-tenant
	// middleware promotes the worker JWT to admin scope for this org.
	if (internal) {
		headers["X-Lobu-Memory-Direct-Auth"] = "1";
	}

	if (sessionId) {
		headers["Mcp-Session-Id"] = sessionId;
	}

	return headers;
}

/**
 * Compute the credential scope key for upstream session isolation. The only
 * configured MCP server is the internal lobu-memory server (per-user scope),
 * so the scope key is always the user id.
 */
export function computeScopeKey(userId: string): string {
	return userId;
}

